package pe.com.asistencia.attendance.domain;
import jakarta.persistence.*; import pe.com.asistencia.employee.domain.Employee; import pe.com.asistencia.schedule.domain.Shift; import java.time.*;
@Entity @Table(name="attendance_days",uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","work_date"}))
public class AttendanceDay {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shift_id") private Shift shift; @Column(name="work_date",nullable=false) private LocalDate workDate; @Column(name="first_entry_at") private Instant firstEntryAt; @Column(name="last_exit_at") private Instant lastExitAt; @Column(name="worked_minutes",nullable=false) private int workedMinutes; @Column(name="late_minutes",nullable=false) private int lateMinutes; @Column(name="early_exit_minutes",nullable=false) private int earlyExitMinutes; @Enumerated(EnumType.STRING) @Column(nullable=false) private AttendanceStatus status=AttendanceStatus.OPEN; @Column(name="calculation_version",nullable=false) private int calculationVersion=1;
 protected AttendanceDay(){} public AttendanceDay(Employee e,LocalDate date,Shift shift){employee=e;workDate=date;this.shift=shift;}
 public void apply(PunchType type,Instant at,ZoneId zone,int entryTolerance,int exitTolerance){if(type==PunchType.ENTRY){if(firstEntryAt==null||at.isBefore(firstEntryAt))firstEntryAt=at;status=AttendanceStatus.OPEN;}else{lastExitAt=at;if(firstEntryAt!=null&&!at.isBefore(firstEntryAt)){workedMinutes=Math.max(0,(int)Duration.between(firstEntryAt,at).toMinutes()-(shift==null?0:shift.getBreakMinutes()));status=AttendanceStatus.COMPLETED;}else status=AttendanceStatus.INCOMPLETE;}recalculateRules(zone,entryTolerance,exitTolerance);}
 public void apply(PunchType type,Instant at,ZoneId zone,int entryTolerance,int exitTolerance,LocalTime expectedStart,LocalTime expectedEnd,boolean crossesMidnight,int breakMinutes){if(type==PunchType.ENTRY){if(firstEntryAt==null||at.isBefore(firstEntryAt))firstEntryAt=at;status=AttendanceStatus.OPEN;}else{lastExitAt=at;if(firstEntryAt!=null&&!at.isBefore(firstEntryAt)){workedMinutes=Math.max(0,(int)Duration.between(firstEntryAt,at).toMinutes()-breakMinutes);status=AttendanceStatus.COMPLETED;}else status=AttendanceStatus.INCOMPLETE;}if(firstEntryAt!=null){Instant expected=workDate.atTime(expectedStart).atZone(zone).toInstant().plusSeconds(entryTolerance*60L);lateMinutes=(int)Math.max(0,Duration.between(expected,firstEntryAt).toMinutes());}if(lastExitAt!=null){LocalDate endDate=crossesMidnight?workDate.plusDays(1):workDate;Instant expected=endDate.atTime(expectedEnd).atZone(zone).toInstant().minusSeconds(exitTolerance*60L);earlyExitMinutes=(int)Math.max(0,Duration.between(lastExitAt,expected).toMinutes());}}
 public void apply(PunchType type,Instant at){apply(type,at,ZoneId.of("UTC"),0,0);}
 private void recalculateRules(ZoneId zone,int entryTolerance,int exitTolerance){if(shift==null)return;if(firstEntryAt!=null){Instant expected=workDate.atTime(shift.getStartTime()).atZone(zone).toInstant().plusSeconds(entryTolerance*60L);lateMinutes=(int)Math.max(0,Duration.between(expected,firstEntryAt).toMinutes());}if(lastExitAt!=null){LocalDate endDate=shift.isCrossesMidnight()?workDate.plusDays(1):workDate;Instant expected=endDate.atTime(shift.getEndTime()).atZone(zone).toInstant().minusSeconds(exitTolerance*60L);earlyExitMinutes=(int)Math.max(0,Duration.between(lastExitAt,expected).toMinutes());}}
 public void markAbsent(){status=AttendanceStatus.ABSENT;}
 public void markIncomplete(){if(status==AttendanceStatus.OPEN&&firstEntryAt!=null&&lastExitAt==null)status=AttendanceStatus.INCOMPLETE;}
 public void markExcused(){if(status!=AttendanceStatus.ABSENT)throw new IllegalStateException("Solo una ausencia puede justificarse");status=AttendanceStatus.EXCUSED;}
 public Long getId(){return id;} public Employee getEmployee(){return employee;} public Shift getShift(){return shift;} public LocalDate getWorkDate(){return workDate;} public Instant getFirstEntryAt(){return firstEntryAt;} public Instant getLastExitAt(){return lastExitAt;} public int getWorkedMinutes(){return workedMinutes;} public int getLateMinutes(){return lateMinutes;} public int getEarlyExitMinutes(){return earlyExitMinutes;} public AttendanceStatus getStatus(){return status;}
}
